        $data['defaultAcrValues'] = $this->getDefaultAcrValues();
        $data['defaultMaxAge'] = $this->getDefaultMaxAge();
        $data['sectorIdentifierUri'] = $this->getSectorIdentifierUri();
        $allowedRedirects = $this->getAllowedRedirects();
        if (null !== $allowedRedirects) {
            $data['allowedRedirects'] = [];
            foreach ($allowedRedirects as $row) {
                if (null !== $row) {
                    $jsonRow = [];
                    $jsonRow['uid'] = $row->uid();
                    $jsonRow['url'] = $row->getUrl();
                    $jsonRow['version'] = $row->getVersion();
                    $data['allowedRedirects'][] = $jsonRow;
                }
            }
        }
        $allowedAudiences = $this->getAllowedAudiences();
        if (null !== $allowedAudiences) {
            $data['allowedAudiences'] = [];
            foreach ($allowedAudiences as $row) {
                if (null !== $row) {
                    $jsonRow = [];
                    $jsonRow['uid'] = $row->uid();
                    $jsonRow['audience'] = $row->getAudience();
                    $jsonRow['version'] = $row->getVersion();
                    $data['allowedAudiences'][] = $jsonRow;
                }
            }
        }
        $data['grantTypesJson'] = $this->getGrantTypesJson();
        $data['isResourceServer'] = $this->isIsResourceServer();
        $data['requirePushedAuthorizationRequests'] = $this->isRequirePushedAuthorizationRequests();
        $data['requirePkce'] = $this->isRequirePkce();
        $data['backChannelLogoutUri'] = $this->getBackChannelLogoutUri();
        $data['backChannelLogoutSessionRequired'] = $this->isBackChannelLogoutSessionRequired();
        $data['frontChannelLogoutUri'] = $this->getFrontChannelLogoutUri();
        $data['frontChannelLogoutSessionRequired'] = $this->isFrontChannelLogoutSessionRequired();
        $data['enabled'] = $this->isEnabled();
        $data['clientName'] = $this->getClientName();
        $data['logoUri'] = $this->getLogoUri();
        $data['clientUri'] = $this->getClientUri();
        $data['policyUri'] = $this->getPolicyUri();
        $data['tosUri'] = $this->getTosUri();
        $data['responseTypesJson'] = $this->getResponseTypesJson();
        $data['dynamicallyRegistered'] = $this->isDynamicallyRegistered();
        $data['registeredAt'] = $this->getRegisteredAt();
        $data['allowedScopesM2m'] = $this->getAllowedScopesM2m();
        $data['m2mTokenTtlSeconds'] = $this->getM2mTokenTtlSeconds();
        $data['requestObjectSigningAlg'] = $this->getRequestObjectSigningAlg();
